SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;



CREATE TABLE `ayarlar` (
  `id` tinyint(4) NOT NULL DEFAULT 1,
  `site_baslik` varchar(255) DEFAULT 'ZiraatBox',
  `site_slogan` varchar(255) DEFAULT 'Çiftçiden Tüketiciye Güvenli İlan Platformu',
  `site_desc` text DEFAULT NULL,
  `site_tel` varchar(20) DEFAULT NULL,
  `site_eposta` varchar(100) DEFAULT NULL,
  `site_adres` text DEFAULT NULL,
  `ilan_suresi_gun` int(11) DEFAULT 30,
  `ilan_onay_gerekiyor` tinyint(4) DEFAULT 1,
  `max_resim_sayisi` int(11) DEFAULT 10,
  `facebook` varchar(255) DEFAULT NULL,
  `instagram` varchar(255) DEFAULT NULL,
  `twitter` varchar(255) DEFAULT NULL,
  `smtp_host` varchar(255) DEFAULT NULL,
  `smtp_user` varchar(255) DEFAULT NULL,
  `smtp_pass` varchar(255) DEFAULT NULL,
  `smtp_port` varchar(10) DEFAULT NULL,
  `bakim_modu` tinyint(1) DEFAULT 0,
  `smtp_secure` varchar(10) DEFAULT 'TLS',
  `hakkimizda` text DEFAULT NULL,
  `kvkk` text DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

\n\nZiraatBox, Türkiye’nin bereketli topraklarında emek veren çiftçilerimizin, tarım işletmelerinin ve hayvancılık sektörünün ihtiyaç duyduğu dijital dönüşüme öncülük etmek amacıyla kurulmuştur. Geleneksel tarım ticaretini modern teknolojinin hızı ve güveniyle birleştiren platformumuz, traktörden ekipmana, hayvancılıktan tarım ürünlerine kadar geniş bir yelpazede alıcı ve satıcıyı bir araya getirmektedir.\n\nVizyonumuz\nTarım ve hayvancılık ekipmanlarına erişimi demokratikleştirmek, ticaretin önündeki coğrafi engelleri kaldırmak ve Türkiye\'nin en büyük, en güvenilir dijital tarım pazar yeri olmaktır.\n\nMisyonumuz\nKullanıcılarımıza en sade, hızlı ve güvenilir ilan yayınlama deneyimini sunarak; doğru ürünün, doğru alıcıyla en uygun fiyata buluşmasını sağlamaktır. ZiraatBox olarak, tarım sektöründeki her paydaşın (çiftçi, bayi, üretici) dijital dünyada güçlü bir yer edinmesine destek oluyoruz.\n\nNeden ZiraatBox?\n\nSektörel Uzmanlık: Biz sadece bir ilan sitesi değiliz; tarımın dilinden anlayan, sektörün ihtiyaçlarına göre özelleştirilmiş bir platformuz.\n\nKolay Kullanım: Karmaşadan uzak, \"Sahibinden\" nizamında, en hızlı şekilde sonuca ulaştıran bir altyapı sunuyoruz.\n\nGüvenli Ticaret: İlan onay mekanizmamız ve filtreleme sistemlerimizle, platformda sadece gerçek ve kaliteli ilanların yer alması için çalışıyoruz.\n\nGeniş Kapsam: Traktör yedek parçasından damızlık hayvan ilanlarına kadar tarımın her dalında uzmanlaşmış kategoriler sunuyoruz.\n\nBugün binlerce kullanıcımızla birlikte Türkiye tarımının gücüne güç katmaya, toprağın bereketini dijital ticaretin hızıyla büyütmeye devam ediyoruz.\n\nZiraatBox.com - Tarımın Kalbi Burada Atıyor.","ZiraatBox Kişisel Verilerin Korunması ve Gizlilik Politikası\n1. VERİ SORUMLUSU\n6698 sayılı Kişisel Verilerin Korunması Kanunu (“KVKK”) uyarınca, ZiraatBox (Bundan sonra “Platform” olarak anılacaktır), kişisel verilerinizi aşağıda açıklanan kapsamda işleyebilecek ve koruyabilecektir.\n\n2. İŞLENEN KİŞİSEL VERİLERİNİZ\nPlatformumuza üye olurken veya ilan verirken paylaştığınız şu veriler işlenmektedir:\n\nKimlik Bilgileri: Ad, soyad, T.C. kimlik numarası (gerektiğinde).\n\nİletişim Bilgileri: Telefon numarası, e-posta adresi, adres bilgileri.\n\nİlan Bilgileri: İlan içeriği, konum bilgileri, ürün fotoğrafları.\n\nİşlem Güvenliği: IP adresi, giriş-çıkış bilgileri, çerez (cookie) verileri.\n\n3. VERİ İŞLEME AMAÇLARIMIZ\nKişisel verileriniz şu amaçlarla işlenmektedir:\n\nİlan yayınlama süreçlerinin yönetilmesi ve alıcı-satıcı iletişiminin kurulması.\n\nPlatform güvenliğinin sağlanması ve sahte ilanların engellenmesi.\n\nYasal yükümlülüklerin (fatura, muhasebe, adli makam talepleri) yerine getirilmesi.\n\nKullanıcı deneyimini iyileştirmek ve teknik destek sunmak.\n\n4. VERİLERİN AKTARILMASI\nKişisel verileriniz, kanunen zorunlu olduğu hallerde adli ve idari makamlara, savunma hakkımızı kullanabilmemiz adına avukatlarımıza ve platformun teknik altyapısını sağlayan iş ortaklarımıza (sunucu hizmetleri vb.) sınırlı kapsamda aktarılabilir. ZiraatBox, kullanıcı verilerini üçüncü taraflara reklam veya pazarlama amacıyla satmaz.\n\n5. VERİ TOPLAMA YÖNTEMİ VE HUKUKİ SEBEBİ\nVerileriniz, web sitemiz üzerindeki formlar, üyelik kayıt ekranları ve ilan giriş panelleri aracılığıyla; sözleşmenin kurulması, ifası ve veri sorumlusunun meşru menfaatleri hukuki sebeplerine dayalı olarak toplanmaktadır.\n\n6. VERİ SAHİBİ OLARAK HAKLARINIZ (Madde 11)\nKanun uyarınca ZiraatBox’a başvurarak şu haklarınızı kullanabilirsiniz:\n\nKişisel verilerinizin işlenip işlenmediğini öğrenme.\n\nİşlenmişse buna ilişkin bilgi talep etme.\n\nEksik veya yanlış işlenmişse bunların düzeltilmesini isteme.\n\nKişisel verilerinizin silinmesini veya yok edilmesini isteme.\n\nVerilerin münhasıran otomatik sistemler vasıtasıyla analiz edilmesi suretiyle aleyhinize bir sonucun ortaya çıkmasına itiraz etme.\n\n7. İLETİŞİM VE BAŞVURU\nKVKK kapsamındaki taleplerinizi, Platformumuzda yer alan iletişim formunu kullanarak veya destek@ziraatbox.com e-posta adresi üzerinden tarafımıza iletebilirsiniz.");


CREATE TABLE `favoriler` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `uye_id` int(10) unsigned NOT NULL,
  `ilan_id` bigint(20) unsigned NOT NULL,
  `eklenen_fiyat` decimal(15,2) DEFAULT 0.00,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



CREATE TABLE `ilan_izlenim_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ilan_id` bigint(20) unsigned NOT NULL,
  `izlenme_tarihi` date NOT NULL,
  `IP_adresi` varchar(45) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ilan_id` (`ilan_id`),
  KEY `izlenme_tarihi` (`izlenme_tarihi`)
) ENGINE=InnoDB AUTO_INCREMENT=250 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



CREATE TABLE `ilan_ozellik_verileri` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ilan_id` bigint(20) unsigned NOT NULL,
  `ozellik_id` int(10) unsigned NOT NULL,
  `deger` text NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ilan_id` (`ilan_id`),
  KEY `ozellik_id` (`ozellik_id`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



CREATE TABLE `ilan_resimleri` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ilan_id` bigint(20) unsigned NOT NULL,
  `dosya_adi` varchar(255) NOT NULL,
  `ana_resim` tinyint(4) DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `ilan_id` (`ilan_id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



CREATE TABLE `ilanlar` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ilan_no` bigint(20) unsigned DEFAULT NULL,
  `uye_id` int(10) unsigned NOT NULL,
  `kategori_id` int(10) unsigned NOT NULL,
  `satici_tipi` enum('Uretici','Bayi','Fabrika','Toptanci') NOT NULL DEFAULT 'Uretici',
  `baslik` varchar(255) NOT NULL,
  `slug` varchar(300) NOT NULL,
  `aciklama` mediumtext NOT NULL,
  `fiyat` decimal(12,2) NOT NULL,
  `il` varchar(60) NOT NULL,
  `ilce` varchar(80) NOT NULL,
  `mahalle` varchar(120) DEFAULT NULL,
  `durum` enum('beklemede','aktif','pasif') DEFAULT 'beklemede',
  `kayit_ip` varchar(45) DEFAULT NULL,
  `bitis_tarihi` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `iletisim_tercihi` enum('hepsi','sadece_telefon','sadece_mesaj') NOT NULL DEFAULT 'hepsi',
  `isim_gizle` tinyint(1) NOT NULL DEFAULT 0,
  `goruntulenme_sayisi` int(11) DEFAULT 0,
  `begeni_sayisi` int(11) DEFAULT 0,
  `ip_adresi` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  UNIQUE KEY `ilan_no` (`ilan_no`),
  KEY `idx_durum_kategori` (`durum`,`kategori_id`),
  KEY `idx_uye_id` (`uye_id`),
  KEY `idx_konum` (`il`,`ilce`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



CREATE TABLE `ilceler` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `il_id` int(11) NOT NULL,
  `ilce_adi` varchar(20) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ilceler_il_id_index` (`il_id`)
) ENGINE=InnoDB AUTO_INCREMENT=974 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ayhan baris 2021';



CREATE TABLE `iller` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `il_adi` varchar(20) NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=82 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='ayhan baris 2021';



CREATE TABLE `kategori_ozellikleri` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `kategori_id` int(10) unsigned NOT NULL,
  `ozellik_id` int(10) unsigned NOT NULL,
